COMMENT ON TABLE neighborhoods IS 'The 8 neighborhoods a new cell is computed from: the cell and its immediate neighbors (left, center, right). Index = left*4 + center*2 + right selects the bit of the rule number.';
COMMENT ON COLUMN neighborhoods.neighborhood_id IS 'n<left><center><right>.';
COMMENT ON COLUMN neighborhoods.left_state IS 'The left neighbor (p).';
COMMENT ON COLUMN neighborhoods.center_state IS 'The cell itself (q).';
COMMENT ON COLUMN neighborhoods.right_state IS 'The right neighbor (r).';

